CREATE FUNCTION public.assert_semester_registration_admin(p_actor uuid,p_tenant uuid,p_permission text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
    IF COALESCE(auth.role(),'')<>'service_role' THEN
        RAISE EXCEPTION 'Trusted backend required' USING ERRCODE='42501';
    END IF;
    PERFORM 1 FROM public.users u JOIN public.user_roles ur ON ur.user_id=u.id
    JOIN public.roles r ON r.id=ur.role_id JOIN public.role_permissions rp ON rp.role_id=r.id
    JOIN public.permissions p ON p.permission_id=rp.permission_id
    JOIN public.institutions i ON i.institution_id=p_tenant
    JOIN public.organizations org ON org.organization_id=i.organization_id
    WHERE u.id=p_actor AND u.status='active' AND r.name='admin' AND r.is_active
      AND ur.scope_type='institution' AND ur.scope_id=p_tenant AND ur.scope_organization_id=i.organization_id
      -- Existing student-account permissions retain their historical global catalogue label;
      -- authority still comes exclusively from this exact institution-scoped admin grant.
      AND i.is_active AND i.status='active' AND org.status='active' AND p.is_active AND p.scope IN ('institution','global')
      AND p.code IN (p_permission,split_part(p_permission,'.',1)||'.*','*')
    FOR SHARE OF u,ur,r,rp,p,i,org;
    IF NOT FOUND THEN RAISE EXCEPTION 'Administrator permission required' USING ERRCODE='42501'; END IF;
END;
$$;

CREATE FUNCTION public.assert_semester_registration_student(p_actor uuid, p_tenant uuid, p_action text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE result uuid;
BEGIN
    IF COALESCE(auth.role(),'')<>'service_role' THEN
        RAISE EXCEPTION 'Trusted backend required' USING ERRCODE='42501';
    END IF;
    SELECT s.student_id INTO result
    FROM public.students s JOIN public.users u ON u.id=s.user_id
    JOIN public.institutions i ON i.institution_id=s.institution_id
    JOIN public.organizations org ON org.organization_id=i.organization_id
    JOIN public.user_roles ur ON ur.user_id=u.id
    JOIN public.roles r ON r.id=ur.role_id
    JOIN public.role_permissions rp ON rp.role_id=r.id
    JOIN public.permissions p ON p.permission_id=rp.permission_id
    WHERE u.id=p_actor AND u.status='active' AND s.institution_id=p_tenant
      AND s.is_active AND s.status='active' AND s.approval_status='approved'
      AND i.is_active AND i.status='active' AND org.status='active'
      AND r.name='student' AND r.is_active AND ur.scope_type='institution'
      AND ur.scope_id=p_tenant AND ur.scope_organization_id=i.organization_id
      AND p.is_active AND p.scope='institution'
      AND p.code IN ('registration.own.'||p_action,'registration.*','*')
    FOR SHARE OF s,u,i,org,ur,r,rp,p;
    IF result IS NULL THEN
        RAISE EXCEPTION 'Approved student with registration permission required' USING ERRCODE='42501';
    END IF;
    RETURN result;
END;
$$;

-- SOURCE option_groups.sql sha256=fd4179891ed3a3473e0303b9507b34da5f97960fffe77bf89de4da2f62ec60f9
CREATE FUNCTION public.manage_curriculum_choice_group(
    p_actor uuid, p_tenant uuid, p_group uuid, p_payload jsonb, p_delete boolean DEFAULT false
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE group_id uuid:=COALESCE(p_group,gen_random_uuid()); version_id uuid; stage_id uuid;
    version_row jsonb; stage_row jsonb; option_row jsonb; option_id uuid;
    subject_id uuid; subject_row record; previous_row jsonb;
BEGIN
    PERFORM public.assert_academic_foundation_actor(p_actor,p_tenant,'courses');
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('academic-setup:'||p_tenant::text,0));
    IF p_group IS NOT NULL THEN
        SELECT to_jsonb(g) INTO previous_row FROM public.curriculum_choice_groups g
        WHERE choice_group_id=p_group AND institution_id=p_tenant FOR UPDATE;
        IF previous_row IS NULL THEN
            RAISE EXCEPTION 'Option group not found' USING ERRCODE='P0002';
        END IF;
    END IF;
    version_id:=COALESCE((previous_row->>'curriculum_version_id')::uuid,(p_payload->>'curriculum_version_id')::uuid);
    stage_id:=COALESCE((previous_row->>'program_semester_id')::uuid,(p_payload->>'program_semester_id')::uuid);
    version_row:=public.academic_structure_parent('curriculum_versions',version_id,p_tenant);
    stage_row:=public.academic_structure_parent('program_semesters',stage_id,p_tenant);
    IF version_row->>'status'<>'draft' OR version_row->>'program_id'<>stage_row->>'program_id'
       OR (stage_row->>'semester_number')::integer>(version_row->>'total_semesters')::integer THEN
        RAISE EXCEPTION 'Edit option groups only in a matching draft curriculum' USING ERRCODE='23514';
    END IF;
    IF p_delete THEN
        DELETE FROM public.curriculum_choice_groups WHERE choice_group_id=p_group AND institution_id=p_tenant;
    ELSE
        IF jsonb_typeof(p_payload->'options') IS DISTINCT FROM 'array'
           OR jsonb_array_length(p_payload->'options') NOT BETWEEN 2 AND 20 THEN
            RAISE EXCEPTION 'Provide two or more complete options' USING ERRCODE='22023';
        END IF;
        IF p_group IS NULL THEN
            INSERT INTO public.curriculum_choice_groups(choice_group_id,institution_id,curriculum_version_id,program_semester_id,name)
            VALUES(group_id,p_tenant,version_id,stage_id,btrim(p_payload->>'name'));
        ELSE
            IF (p_payload->>'curriculum_version_id')::uuid IS DISTINCT FROM version_id
               OR (p_payload->>'program_semester_id')::uuid IS DISTINCT FROM stage_id THEN
                RAISE EXCEPTION 'Option group relationships are immutable' USING ERRCODE='22023';
            END IF;
            UPDATE public.curriculum_choice_groups SET name=btrim(p_payload->>'name') WHERE choice_group_id=group_id;
            DELETE FROM public.curriculum_choice_options WHERE choice_group_id=group_id;
        END IF;
        FOR option_row IN SELECT value FROM jsonb_array_elements(p_payload->'options') LOOP
            IF jsonb_typeof(option_row->'curriculum_subject_ids') IS DISTINCT FROM 'array'
               OR jsonb_array_length(option_row->'curriculum_subject_ids') NOT BETWEEN 1 AND 64 THEN
                RAISE EXCEPTION 'Every option requires subjects' USING ERRCODE='22023';
            END IF;
            INSERT INTO public.curriculum_choice_options(institution_id,choice_group_id,name)
            VALUES(p_tenant,group_id,btrim(option_row->>'name')) RETURNING choice_option_id INTO option_id;
            FOR subject_id IN SELECT value::uuid FROM jsonb_array_elements_text(option_row->'curriculum_subject_ids') LOOP
                SELECT * INTO subject_row FROM public.curriculum_subjects
                WHERE curriculum_subject_id=subject_id AND institution_id=p_tenant;
                IF NOT FOUND OR subject_row.curriculum_version_id<>version_id
                   OR subject_row.program_semester_id<>stage_id OR NOT subject_row.is_active OR subject_row.is_required THEN
                    RAISE EXCEPTION 'Option subjects must be active optional mappings in this semester' USING ERRCODE='23514';
                END IF;
                IF EXISTS(SELECT 1 FROM public.curriculum_choice_subjects cs
                    JOIN public.curriculum_choice_options co USING(choice_option_id)
                    WHERE cs.curriculum_subject_id=subject_id AND co.choice_group_id<>group_id) THEN
                    RAISE EXCEPTION 'Subject already belongs to another choice group' USING ERRCODE='23514';
                END IF;
                INSERT INTO public.curriculum_choice_subjects VALUES(p_tenant,option_id,subject_id);
            END LOOP;
        END LOOP;
    END IF;
    INSERT INTO public.admin_audit_log(actor_user_id,institution_id,action,table_name,record_id,record_data)
    VALUES(p_actor,p_tenant,'academic.choice_group.'||CASE WHEN p_delete THEN 'delete' ELSE 'save' END,
        'curriculum_choice_groups',group_id::text,jsonb_build_object('before',previous_row,'after',p_payload));
    RETURN jsonb_build_object('choice_group_id',group_id,'institution_id',p_tenant);
END;
$$;

-- SOURCE guards.sql sha256=adfd3b6bb18654d0a7ddd2df6522b4640b17282cdc4f8b9f9b96cb4b98157f7e
CREATE FUNCTION public.guard_semester_registration_structure() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE tenant uuid:=NEW.institution_id; group_id uuid; used_count bigint;
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('academic-setup:'||tenant::text,0));
    IF TG_TABLE_NAME='curriculum_subjects' THEN
        IF (NOT NEW.is_active OR NEW.is_required) AND EXISTS(
            SELECT 1 FROM public.curriculum_choice_subjects WHERE curriculum_subject_id=NEW.curriculum_subject_id
        ) THEN
            RAISE EXCEPTION 'Remove this subject from draft options before changing its status' USING ERRCODE='23514';
        END IF;
    ELSIF TG_TABLE_NAME='curriculum_versions' THEN
        IF OLD.status='draft' AND NEW.status='published' THEN
            FOR group_id IN SELECT choice_group_id FROM public.curriculum_choice_groups
                WHERE curriculum_version_id=NEW.curriculum_version_id LOOP
                IF (SELECT count(*) FROM public.curriculum_choice_options WHERE choice_group_id=group_id)<2
                   OR EXISTS(SELECT 1 FROM public.curriculum_choice_options co
                       WHERE co.choice_group_id=group_id AND NOT EXISTS(
                           SELECT 1 FROM public.curriculum_choice_subjects cs WHERE cs.choice_option_id=co.choice_option_id
                       )) THEN
                    RAISE EXCEPTION 'Complete every subject option before publishing' USING ERRCODE='23514';
                END IF;
            END LOOP;
        END IF;
    ELSIF TG_TABLE_NAME='academic_offerings' THEN
        SELECT count(*) INTO used_count FROM public.student_offering_enrollments
        WHERE academic_offering_id=NEW.academic_offering_id;
        IF used_count>0 AND (NOT NEW.is_active OR (NEW.capacity IS NOT NULL AND NEW.capacity<used_count)) THEN
            RAISE EXCEPTION 'Offering has registered students' USING ERRCODE='23514';
        END IF;
    ELSIF TG_TABLE_NAME='academic_sections' THEN
        SELECT count(*) INTO used_count FROM public.student_semester_registrations
        WHERE academic_section_id=NEW.academic_section_id;
        IF used_count>0 AND (NOT NEW.is_active OR (NEW.capacity IS NOT NULL AND NEW.capacity<used_count)) THEN
            RAISE EXCEPTION 'Section has assigned students' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

-- SOURCE assignments.sql sha256=b9151324aed9110e2f2a3377ce24ecac4fb04a6e02b9a0547a1456b9e3d5d372
CREATE FUNCTION public.assign_student_semester(p_actor uuid,p_tenant uuid,p_student uuid,p_section uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE section_row jsonb; result public.student_semester_registrations; student_row record;
BEGIN
    PERFORM public.assert_academic_foundation_actor(p_actor,p_tenant,'courses');
    PERFORM public.assert_semester_registration_admin(p_actor,p_tenant,'students.update');
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('academic-setup:'||p_tenant::text,0));
    SELECT * INTO student_row FROM public.students
    WHERE student_id=p_student AND institution_id=p_tenant FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Student not found' USING ERRCODE='P0002'; END IF;
    IF student_row.approval_status<>'approved' OR NOT student_row.is_active OR student_row.status<>'active' THEN
        RAISE EXCEPTION 'Assign only approved active students' USING ERRCODE='23514';
    END IF;
    section_row:=public.academic_structure_parent('academic_sections',p_section,p_tenant);
    IF EXISTS(SELECT 1 FROM public.student_semester_registrations reg
        JOIN public.academic_sections sec USING(academic_section_id)
        WHERE reg.student_id=p_student AND sec.admission_cohort_id<>(section_row->>'admission_cohort_id')::uuid) THEN
        RAISE EXCEPTION 'Student already belongs to another batch; a transfer requires a separate workflow' USING ERRCODE='23514';
    END IF;
    SELECT * INTO result FROM public.student_semester_registrations
    WHERE student_id=p_student AND semester_id=(section_row->>'semester_id')::uuid FOR UPDATE;
    IF FOUND THEN
        IF result.academic_section_id=p_section THEN RETURN to_jsonb(result); END IF;
        IF result.status='registered' THEN
            RAISE EXCEPTION 'Completed registration cannot be reassigned' USING ERRCODE='P1004';
        END IF;
    END IF;
    IF (section_row->>'capacity') IS NOT NULL AND
       (SELECT count(*) FROM public.student_semester_registrations WHERE academic_section_id=p_section)
           >=(section_row->>'capacity')::integer THEN
        RAISE EXCEPTION 'Section capacity reached' USING ERRCODE='P1002';
    END IF;
    INSERT INTO public.student_semester_registrations(institution_id,student_id,academic_section_id,semester_id)
    VALUES(p_tenant,p_student,p_section,(section_row->>'semester_id')::uuid)
    ON CONFLICT(student_id,semester_id) DO UPDATE SET academic_section_id=EXCLUDED.academic_section_id,assigned_at=now()
    RETURNING * INTO result;
    INSERT INTO public.admin_audit_log(actor_user_id,institution_id,action,table_name,record_id,record_data)
    VALUES(p_actor,p_tenant,'academic.semester.assign','student_semester_registrations',result.semester_registration_id::text,
        jsonb_build_object('after',to_jsonb(result)));
    RETURN to_jsonb(result);
END;
$$;

-- SOURCE registration.sql sha256=17c965ad97886a99955e02ae4a338fccd03271d39a046274735958e6886e6bc4
CREATE FUNCTION public.complete_student_semester(
    p_actor uuid,p_tenant uuid,p_registration uuid,p_options uuid[]
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE resolved_student uuid; registration public.student_semester_registrations;
    section_row jsonb; cohort_row jsonb; offering record; required_ids uuid[];
    chosen_ids uuid[]; group_count integer; enrolled_count integer:=0; canonical_options uuid[];
BEGIN
    resolved_student:=public.assert_semester_registration_student(p_actor,p_tenant,'manage');
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('academic-setup:'||p_tenant::text,0));
    SELECT * INTO registration FROM public.student_semester_registrations reg
    WHERE reg.semester_registration_id=p_registration AND reg.student_id=resolved_student AND reg.institution_id=p_tenant
    FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Assigned semester not found' USING ERRCODE='P0002'; END IF;
    SELECT COALESCE(array_agg(item ORDER BY item),'{}'::uuid[]) INTO canonical_options FROM unnest(p_options) item;
    IF registration.status='registered' THEN
        IF registration.selected_option_ids=canonical_options THEN RETURN to_jsonb(registration); END IF;
        RAISE EXCEPTION 'Registration is already complete' USING ERRCODE='P1004';
    END IF;
    section_row:=public.academic_structure_parent('academic_sections',registration.academic_section_id,p_tenant);
    cohort_row:=public.academic_structure_parent('admission_cohorts',(section_row->>'admission_cohort_id')::uuid,p_tenant);
    IF EXISTS(SELECT 1 FROM public.semesters WHERE semester_id=registration.semester_id AND end_date<current_date) THEN
        RAISE EXCEPTION 'The teaching term has ended' USING ERRCODE='P1001';
    END IF;
    SELECT count(*) INTO group_count FROM public.curriculum_choice_groups
    WHERE curriculum_version_id=(cohort_row->>'curriculum_version_id')::uuid
      AND program_semester_id=(section_row->>'program_semester_id')::uuid;
    IF cardinality(p_options) IS DISTINCT FROM group_count OR EXISTS(
        SELECT 1 FROM public.curriculum_choice_groups g
        WHERE g.curriculum_version_id=(cohort_row->>'curriculum_version_id')::uuid
          AND g.program_semester_id=(section_row->>'program_semester_id')::uuid
          AND (SELECT count(*) FROM public.curriculum_choice_options co
               WHERE co.choice_group_id=g.choice_group_id AND co.choice_option_id=ANY(p_options))<>1
    ) OR (SELECT count(DISTINCT item) FROM unnest(p_options) item)<>group_count THEN
        RAISE EXCEPTION 'Choose exactly one complete option per group' USING ERRCODE='P1003';
    END IF;
    SELECT COALESCE(array_agg(curriculum_subject_id),'{}'::uuid[]) INTO required_ids
    FROM public.curriculum_subjects WHERE curriculum_version_id=(cohort_row->>'curriculum_version_id')::uuid
      AND program_semester_id=(section_row->>'program_semester_id')::uuid AND is_active AND is_required;
    SELECT ARRAY(SELECT DISTINCT item FROM unnest(required_ids||ARRAY(
        SELECT curriculum_subject_id FROM public.curriculum_choice_subjects WHERE choice_option_id=ANY(p_options)
    )) item) INTO chosen_ids;
    IF cardinality(chosen_ids)=0 THEN
        RAISE EXCEPTION 'No subjects are configured for registration' USING ERRCODE='P1001';
    END IF;
    FOR offering IN SELECT ao.*,to_jsonb(c) AS snapshot FROM public.academic_offerings ao
        JOIN public.curriculum_subjects cs USING(curriculum_subject_id)
        JOIN public.courses c USING(course_id)
        WHERE ao.academic_section_id=registration.academic_section_id AND ao.institution_id=p_tenant
          AND ao.is_active AND cs.curriculum_subject_id=ANY(chosen_ids)
        ORDER BY ao.academic_offering_id LOOP
        PERFORM public.academic_structure_parent('curriculum_subjects',offering.curriculum_subject_id,p_tenant);
        IF offering.capacity IS NOT NULL AND
           (SELECT count(*) FROM public.student_offering_enrollments WHERE academic_offering_id=offering.academic_offering_id)>=offering.capacity THEN
            RAISE EXCEPTION 'A selected subject has reached capacity' USING ERRCODE='P1002';
        END IF;
        INSERT INTO public.student_offering_enrollments(institution_id,semester_registration_id,academic_offering_id,subject_snapshot)
        VALUES(p_tenant,p_registration,offering.academic_offering_id,
            jsonb_build_object('course_id',offering.snapshot->'course_id','name',offering.snapshot->'name',
                'code',offering.snapshot->'code','credits',offering.snapshot->'credits'));
        enrolled_count:=enrolled_count+1;
    END LOOP;
    IF enrolled_count<>cardinality(chosen_ids) THEN
        RAISE EXCEPTION 'All subjects in the selection must have active offerings' USING ERRCODE='P1001';
    END IF;
    UPDATE public.student_semester_registrations SET status='registered',selected_option_ids=canonical_options,registered_at=now()
    WHERE semester_registration_id=p_registration RETURNING * INTO registration;
    INSERT INTO public.admin_audit_log(actor_user_id,institution_id,action,table_name,record_id,record_data)
    VALUES(p_actor,p_tenant,'academic.semester.register','student_semester_registrations',p_registration::text,
        jsonb_build_object('after',to_jsonb(registration),'subject_count',enrolled_count));
    RETURN to_jsonb(registration);
END;
$$;

-- SOURCE student_reads.sql sha256=492733fbc9d287e28a571a88841243f1d83d31fc20e270c8d5732d4d8f54120d
CREATE FUNCTION public.curriculum_choices_json(p_tenant uuid,p_version uuid DEFAULT NULL,p_stage uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
    SELECT COALESCE(jsonb_agg(to_jsonb(g)||jsonb_build_object('options',(
        SELECT COALESCE(jsonb_agg(to_jsonb(co)||jsonb_build_object('curriculum_subject_ids',(
            SELECT COALESCE(jsonb_agg(cs.curriculum_subject_id ORDER BY cs.curriculum_subject_id),'[]'::jsonb)
            FROM public.curriculum_choice_subjects cs WHERE cs.choice_option_id=co.choice_option_id
        )) ORDER BY co.name,co.choice_option_id),'[]'::jsonb)
        FROM public.curriculum_choice_options co WHERE co.choice_group_id=g.choice_group_id
    )) ORDER BY g.name,g.choice_group_id),'[]'::jsonb)
    FROM public.curriculum_choice_groups g WHERE g.institution_id=p_tenant
      AND (p_version IS NULL OR g.curriculum_version_id=p_version)
      AND (p_stage IS NULL OR g.program_semester_id=p_stage);
$$;

CREATE FUNCTION public.read_curriculum_choices(p_actor uuid,p_tenant uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
    PERFORM public.assert_semester_registration_admin(p_actor,p_tenant,'courses.read');
    RETURN public.curriculum_choices_json(p_tenant);
END;
$$;

CREATE FUNCTION public.read_student_semesters(p_actor uuid,p_tenant uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE resolved_student uuid; result jsonb;
BEGIN
    resolved_student:=public.assert_semester_registration_student(p_actor,p_tenant,'read');
    SELECT COALESCE(jsonb_agg(to_jsonb(reg)||jsonb_build_object(
        'section_name',sec.name,'batch_name',cohort.name,'program_name',program.name,
        'program_semester_name',stage.name,'term_name',term.name,
        'start_date',term.start_date,'end_date',term.end_date,
        'groups',public.curriculum_choices_json(p_tenant,cohort.curriculum_version_id,sec.program_semester_id),
        'subjects',(
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'curriculum_subject_id',cs.curriculum_subject_id,'name',c.name,'code',c.code,
                'credits',c.credits,'is_required',cs.is_required,
                'academic_offering_id',ao.academic_offering_id,
                'available',COALESCE(ao.is_active AND c.is_active AND sec.is_active AND cohort.is_active
                    AND term.is_active AND term.end_date>=current_date AND (
                        ao.capacity IS NULL OR (SELECT count(*) FROM public.student_offering_enrollments soe
                        WHERE soe.academic_offering_id=ao.academic_offering_id)<ao.capacity
                    ),false)
            ) ORDER BY c.name,cs.curriculum_subject_id),'[]'::jsonb)
            FROM public.curriculum_subjects cs JOIN public.courses c USING(course_id)
            LEFT JOIN public.academic_offerings ao ON ao.curriculum_subject_id=cs.curriculum_subject_id
                AND ao.academic_section_id=sec.academic_section_id
            WHERE cs.curriculum_version_id=cohort.curriculum_version_id
                AND cs.program_semester_id=sec.program_semester_id AND cs.is_active
        ),
        'enrolled_subjects',(
            SELECT COALESCE(jsonb_agg(soe.subject_snapshot ORDER BY soe.subject_snapshot->>'name'),'[]'::jsonb)
            FROM public.student_offering_enrollments soe WHERE soe.semester_registration_id=reg.semester_registration_id
        )
    ) ORDER BY term.start_date DESC,reg.semester_registration_id),'[]'::jsonb) INTO result
    FROM public.student_semester_registrations reg
    JOIN public.academic_sections sec USING(academic_section_id)
    JOIN public.admission_cohorts cohort USING(admission_cohort_id)
    JOIN public.programs program ON program.program_id=cohort.program_id
    JOIN public.program_semesters stage ON stage.program_semester_id=sec.program_semester_id
    JOIN public.semesters term ON term.semester_id=reg.semester_id
    WHERE reg.student_id=resolved_student AND reg.institution_id=p_tenant;
    RETURN jsonb_build_object('institution_id',p_tenant,'items',result);
END;
$$;

-- SOURCE security.sql sha256=95e30549e93855812667e5e030c1edf4bc47a005189ea157b21b680796b97bde
DO $$
DECLARE relation_name text;
BEGIN
    FOREACH relation_name IN ARRAY ARRAY['curriculum_choice_groups','curriculum_choice_options',
        'curriculum_choice_subjects','student_semester_registrations','student_offering_enrollments'] LOOP
        EXECUTE format('ALTER TABLE public.%I OWNER TO postgres',relation_name);
        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',relation_name);
        EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC,anon,authenticated,service_role',relation_name);
        EXECUTE format('GRANT SELECT ON TABLE public.%I TO service_role',relation_name);
    END LOOP;
    FOREACH relation_name IN ARRAY ARRAY['curriculum_versions','curriculum_subjects','academic_sections','academic_offerings'] LOOP
        EXECUTE format('CREATE TRIGGER registration_structure_guard BEFORE UPDATE ON public.%I
            FOR EACH ROW EXECUTE FUNCTION public.guard_semester_registration_structure()',relation_name);
    END LOOP;
END;
$$;
REVOKE ALL ON FUNCTION public.assert_semester_registration_admin(uuid,uuid,text),
    public.assert_semester_registration_student(uuid,uuid,text),
    public.curriculum_choices_json(uuid,uuid,uuid),public.guard_semester_registration_structure(),
    public.read_curriculum_choices(uuid,uuid),public.read_student_semesters(uuid,uuid),
    public.manage_curriculum_choice_group(uuid,uuid,uuid,jsonb,boolean),
    public.assign_student_semester(uuid,uuid,uuid,uuid),
    public.complete_student_semester(uuid,uuid,uuid,uuid[])
    FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.read_curriculum_choices(uuid,uuid),public.read_student_semesters(uuid,uuid),
    public.manage_curriculum_choice_group(uuid,uuid,uuid,jsonb,boolean),
    public.assign_student_semester(uuid,uuid,uuid,uuid),
    public.complete_student_semester(uuid,uuid,uuid,uuid[]) TO service_role;
NOTIFY pgrst,'reload schema';
COMMIT;
